// thrFieldsX64 returns the x86_64 Thread field map for a given Dart version.
func thrFieldsX64(dartVersion string) map[int]string {
	// PHASE 6: check non-compressed tables first (Dart 2.x)
	if t := thrFieldsX64Nocompress(dartVersion); t != nil {
		return t
	}
	switch dartVersion {
	case "2.18.0":
		return thrV2180_x64
	case "2.19.0":
		return thrV2190_x64
	case "3.0.5":
		return thrV305_x64
	case "3.1.0":
		return thrV310_x64
	case "3.2.5", "3.3.0":
		return thrV325_x64
	case "3.4.3", "3.5.0":
		return thrV343_x64
	case "3.6.2", "3.7.0":
		return thrV362_x64
	case "3.8.1":
		return thrV381_x64
	case "3.9.2":
		return thrV392_x64
	case "3.10.7":
		return thrV3107_x64
	case "3.11.0":
		return thrV3110_x64
	case "3.12.0-dev", "3.12.2":
		return thrV3122_x64
	case "3.13.0":
		return thrV3130_x64
	}
	return nil
}

