// thrFieldsX64Nocompress returns x86_64 non-compressed THR tables for Dart 2.x.
func thrFieldsX64Nocompress(dartVersion string) map[int]string {
	switch dartVersion {
	case "2.10.0":
		return thrV2100_x64_nocompress
	case "2.12.0":
		return thrV2120_x64_nocompress
	case "2.13.0":
		return thrV2130_x64_nocompress
	case "2.14.0":
		return thrV2140_x64_nocompress
	case "2.15.0":
		return thrV2150_x64_nocompress
	case "2.16.0":
		return thrV2160_x64_nocompress
	case "2.17.6":
		return thrV2176_x64_nocompress
	}
	return nil
}

// H-8 fix: merge runtime entry point names into x64 THR tables.
// Same mechanism as thrfields.go's init() for ARM64 — the runtime entry
// name lists are architecture-independent (just function names), only the
// base offsets differ per architecture.
func init() {
	// v2.18/v2.19 use same runtime entries as v2.17.6
	mergeRuntimeEntries(thrV2180_x64, 0x310, runtimeEntriesV217)
	mergeRuntimeEntries(thrV2190_x64, 0x328, runtimeEntriesV217)
	// v3.0.5: no runtime entries list (same as ARM64 v3.0.5)
	mergeRuntimeEntries(thrV310_x64, 0x2c8, runtimeEntriesV310)
	mergeRuntimeEntries(thrV325_x64, 0x2c8, runtimeEntriesV325)
	mergeRuntimeEntries(thrV343_x64, 0x2d0, runtimeEntriesV343)
	mergeRuntimeEntries(thrV362_x64, 0x2e8, runtimeEntriesV362)
	mergeRuntimeEntries(thrV381_x64, 0x2e0, runtimeEntriesV381)
	mergeRuntimeEntries(thrV392_x64, 0x2f0, runtimeEntriesV392)
	// v3.10.7+: LEAF entries in separate block after exit_through_ffi
	mergeRuntimeEntries(thrV3107_x64, 0x2e8, runtimeEntriesV3107)
	mergeRuntimeEntries(thrV3107_x64, 0x6b0, leafEntriesV3107)
	mergeRuntimeEntries(thrV3110_x64, 0x2f0, runtimeEntriesV3115)
	mergeRuntimeEntries(thrV3110_x64, 0x6c0, leafEntriesV3115)
	mergeRuntimeEntries(thrV3122_x64, 0x2f0, runtimeEntriesV3122)
	mergeRuntimeEntries(thrV3122_x64, 0x6c8, leafEntriesV3122)
}

